/// <summary>
/// Extension of method initFromSalesTable
/// </summary>
/// <param name = "_salesTable">SalesTable</param>
void  initFromSalesTable(SalesTable _salesTable)
{
    PurchTable              avaPurchTable_IC        = _salesTable.referencePurchTable();
    SalesTable              avaSalesTable_IC        = avaPurchTable_IC.interCompanySalesTable();

    next initFromSalesTable(_salesTable);

    this.KCS_PurchRefDate               = _salesTable.KCS_PurchRefDate;
    this.AVASalesGroup                  = _salesTable.SalesGroup;
    this.AVAContactName                 = ContactPerson::avaGetContactNameWithTitle(_salesTable.ContactPersonId, _salesTable.LanguageId);
    this.AVADlvReason                   = _salesTable.DlvReason;
    this.AVAVATNum                      = _salesTable.VATNum;
    this.KCS_DecreaseProf               = _salesTable.KCS_DecreaseProf;
    this.AVADlvResponsible              = _salesTable.AVADlvResponsible;
    this.AVASQClerk                     = _salesTable.AVASQClerk;
    this.AVAShipCarrierDeliveryContact  = _salesTable.AVAShipCarrierDeliveryContact;
    this.AVAShipCarrierDeliveryMobile   = _salesTable.AVAShipCarrierDeliveryMobile;
    this.NDX_ShipCarrierDeliveryFax     = _salesTable.NDX_ShipCarrierDeliveryFax;
    this.NDX_ShipCarrierDeliveryPhone   = _salesTable.NDX_ShipCarrierDeliveryPhone;
    this.AVAValutaExtensionDays         = _salesTable.AVAValutaExtensionDays;
    this.AVAPreferenceOutput            = _salesTable.AVAPreferenceOutput;

    this.DeliveryName       = this.avaUpdateDeliveryName(_salesTable);

    if(avaSalesTable_IC)
    {
        changecompany(avaSalesTable_IC.InterCompanyCompanyId)
        {
            this.AVAInventSiteId    = avaSalesTable_IC.InventSiteId;
        }
    }
    else
    {
        this.AVAInventSiteId        = _salesTable.InventSiteId;
    }
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_salesTable">SalesTable</param>
/// <returns>CustName</returns>
public CustName avaUpdateDeliveryName(SalesTable _salesTable)
{
    LogisticsPostalAddress logisticsPostalAddressLoc = _salesTable.deliveryAddress();
    CustName avaNameLoc;

    if(logisticsPostalAddressLoc.NDXLogisticsLocationName1)
    {
        avaNameLoc = logisticsPostalAddressLoc.NDXLogisticsLocationName1;
    }

    if(logisticsPostalAddressLoc.NDXLogisticsLocationName2)
    {
        if(avaNameLoc != '')
        {
            avaNameLoc += '\n';
        }

        avaNameLoc += logisticsPostalAddressLoc.NDXLogisticsLocationName2;
    }

    if(logisticsPostalAddressLoc.NDXLogisticsLocationName3)
    {
        if(avaNameLoc != '')
        {
            avaNameLoc += '\n';
        }

        avaNameLoc += '\n' + logisticsPostalAddressLoc.NDXLogisticsLocationName3;
    }

    return avaNameLoc;
}

/// <summary>
/// AVA_008475_CustCredit
/// </summary>
void avaSetEstimate()
{
    SalesTable  locSalesTable;

    if (CustTable::find(this.InvoiceAccount).MandatoryCreditLimit)
    {
        locSalesTable = this.salesTable(true);
        if (locSalesTable.setEstimate())
        {
            locSalesTable.update();
        }
    }
}

public void insert()
{
    next insert();
    this.avaSetEstimate();
}
